/*
  # الانضباط الطلابي - المرحلة 5: الفئات 2 و3 و4 بنص المواد 6 و7 و8 (القرار 279/2025)

  - النص أدخله المستخدم من اللائحة؛ صُححت عيوب الاستخراج وأُكملت الأرقام المفقودة بالتسلسل.
  - المادة 7 البند 13 (أ–ل): كل فقرة بسجل مستقل (13/أ ... 13/ل).
  - تبقى الحالة pending_review حتى يطابقها المسؤول مع الأصل ويعتمدها.
  - الإصدارات المزروعة من الملخص تُحفظ superseded ولا تُحذف.
*/

ALTER TABLE incident_actions DROP CONSTRAINT IF EXISTS incident_actions_action_type_check;
ALTER TABLE incident_actions ADD CONSTRAINT incident_actions_action_type_check CHECK (action_type IN (
  'guidance','verbal_warning','written_warning','guardian_summons','pledge',
  'extra_tasks','apology','committee_referral','investigation',
  'recommendation','decision','followup_closure','activity_suspension','manazil_transfer',
  'device_confiscation','class_suspension','class_transfer','bus_suspension','grade_cancellation','zero_results'));

UPDATE violations_catalog SET status = 'superseded'
 WHERE category_id IN (2,3,4) AND version = 1 AND status = 'pending_review' AND source LIKE 'ملخص صفحة الوزارة%';

UPDATE violation_categories SET remedies_status='pending_review', remedies_summary='["التنبيه الشفوي الانفرادي", "الإنذار الكتابي", "استدعاء ولي الأمر وأخذ تعهد كتابي على الطالب وولي الأمر بعدم تكرار المخالفة", "تكليف الطالب بمهام إضافية", "اعتذار الطالب إلى من أساء إليه", "التعليق المؤقت عن بعض الأنشطة أو الفعاليات أو الرحلات لمدة لا تجاوز فصلًا دراسيًا بقرار من لجنة الانضباط", "التحفظ على الأجهزة الإلكترونية محل المخالفة (للبند 10) حتى نهاية ذات الفصل", "تعليق دخول الصف من يوم إلى عشرة أيام دراسية مع مهام اجتماعية والسماح بالتطبيقات والامتحانات", "النقل إلى «منازل» لمن تجاوز مرحلة الإلزام"]'::jsonb WHERE id=2;
UPDATE violation_categories SET remedies_status='pending_review', remedies_summary='["الإنذار الكتابي", "استدعاء ولي الأمر وأخذ تعهد كتابي على الطالب وولي الأمر", "تكليف الطالب بمهام إضافية", "نقل الطالب إلى صف آخر", "تعليق استعمال المواصلات المدرسية حتى عام دراسي (للبند 5)", "إلغاء درجة التطبيقات والأنشطة أو الامتحان محل المخالفة", "تعليق دخول الصف من عشرة أيام دراسية إلى فصل دراسي مع مهام اجتماعية والسماح بالتطبيقات والامتحانات", "شطب نتائج الفصل الدراسي ورصد درجة (صفر)", "النقل إلى «منازل» لمن تجاوز مرحلة الإلزام"]'::jsonb WHERE id=3;
UPDATE violation_categories SET remedies_status='pending_review', remedies_summary='["تعليق دخول الصف من عشرة أيام دراسية إلى عام دراسي مع مهام اجتماعية والسماح بالتطبيقات والامتحانات", "شطب نتائج الفصل الدراسي ورصد درجة (صفر)", "النقل إلى «منازل» لمن تجاوز مرحلة الإلزام"]'::jsonb WHERE id=4;

INSERT INTO violations_catalog (code, version, category_id, article, clause, official_name, reference_text, allowed_remedies, remedy_conditions, approval_requirements, status, last_reviewed, source)
SELECT v.code, 2, v.cat, v.art, v.clause, v.name, v.ref, v.rem::jsonb,
  CASE v.cat WHEN 2 THEN 'المادة 6 ثانيًا: (3) استدعاء ولي الأمر وأخذ تعهد كتابي على الطالب وولي الأمر بعدم تكرار المخالفة؛ (6) التعليق عن الأنشطة لمدة لا تجاوز فصلًا دراسيًا بقرار من لجنة الانضباط الطلابي؛ (7) التحفظ على الأجهزة لمدة لا تزيد على نهاية ذات الفصل الدراسي للمخالفة (10) فقط؛ (8) تعليق دخول الصف من يوم إلى عشرة أيام دراسية وفقًا لطبيعة المخالفة وتكرارها مع مهام اجتماعية والسماح بإنجاز التطبيقات والأنشطة وأداء الامتحانات؛ (9) النقل إلى «منازل» لمن تجاوز مرحلة الإلزام.' WHEN 3 THEN 'المادة 7 ثانيًا: (2) استدعاء ولي الأمر وأخذ تعهد كتابي على الطالب وولي الأمر بعدم تكرار المخالفة؛ (5) تعليق المواصلات المدرسية لمدة لا تزيد على عام دراسي للمخالفة (5) وفقًا لطبيعتها؛ (6) إلغاء درجة التطبيقات والأنشطة أو الامتحان محل المخالفة، وورد النص بالإشارة إلى المخالفتين (8) و(9) — يُراجع على الأصل؛ (7) تعليق دخول الصف من عشرة أيام دراسية إلى فصل دراسي وفقًا لطبيعة المخالفة وتكرارها مع مهام اجتماعية والسماح بإنجاز التطبيقات وأداء الامتحانات؛ (8) شطب نتائج الفصل الدراسي ورصد درجة (صفر)؛ (9) النقل إلى «منازل» لمن تجاوز مرحلة الإلزام.' ELSE 'المادة 8 ثانيًا: (1) تعليق دخول الصف من عشرة أيام دراسية إلى عام دراسي وفقًا لطبيعة المخالفة وتكرارها مع مهام اجتماعية والسماح بإنجاز التطبيقات وأداء الامتحانات؛ (2) شطب نتائج الفصل الدراسي ورصد درجة (صفر)؛ (3) النقل إلى «منازل» لمن تجاوز مرحلة الإلزام.' END,
  CASE v.cat WHEN 2 THEN 'التعليق عن الأنشطة بقرار من لجنة الانضباط الطلابي' WHEN 3 THEN 'تعليق الصف/النقل إلى منازل وفق مواد الإحالة والاعتماد (م9–م14)' ELSE 'تعليق الصف/النقل إلى منازل وفق مواد الإحالة والاعتماد (م9–م14)' END,
  'pending_review', current_date,
  'نص اللائحة (القرار 279/2025) المواد 6-8 — أدخله المستخدم؛ يُطابَق مع الأصل قبل الاعتماد'
